// Ranked comparison prep: sort desc, keep values, flag small-n (plain JS)
function ranked(rows) {
  return [...rows]
    .sort((a, b) => b.value - a.value)
    .map((r, i) => ({ ...r, rank: i + 1, thin: r.n != null && r.n < 30 }));
}
// thin flags small-sample bars: rank shown, trust qualified (Ch.1 honesty).

