function ranked(rows) {
  return [...rows].sort((a, b) => b.value - a.value).map((r, i) => ({ ...r, rank: i + 1 }));
}
const cats = [
  { name: 'shoes', value: 368 },
  { name: 'apparel', value: 59 },
  { name: 'hats', value: 210 },
];
const r = ranked(cats);
console.log(r.map((x) => x.rank + '.' + x.name).join(','));
console.log('leader=' + r[0].name + ' margin=' + (r[0].value - r[1].value));

